#include <iostream>
using namespace std;
struct Node {
    int val;
    Node* next;
};

int main() {
    Node* second = new Node;
    second->val = 2;
    second->next = NULL;
    Node* head = new Node;
    head->val = 1;
    head->next = second;
    Node* p = head;
    while (p != NULL) {
        cout << p->val << endl;
        p = p->next;
    }
    return 0;
}
